from collections import deque
# find 4conn 1 components
seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if a[r][c]==1 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));co=[]
   while q:
    x,y=q.pop();co.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(x+dx,y+dy)
     if 0<=z[0]<h and 0<=z[1]<w and a[z[0]][z[1]]==1 and z not in seen:seen.add(z);q.append(z)
   comps.append(co)
# inspect bbox and cavity detection each
sel=[]
for co in comps:
 r0=min(x for x,y in co);r1=max(x for x,y in co);c0=min(y for x,y in co);c1=max(y for x,y in co)
 zeros={(x,y) for x in range(r0,r1+1) for y in range(c0,c1+1) if a[x][y]==0};
 # bbox-local flood zeros; enclosed if not reachable from bbox edge
 q=deque(z for z in zeros if z[0] in (r0,r1) or z[1] in (c0,c1)); reach=set(q)
 while q:
  x,y=q.popleft()
  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
   z=x+dx,y+dy
   if z in zeros and z not in reach:reach.add(z);q.append(z)
 cav=zeros-reach
 if cav: sel.append((co,cav,(r0,r1,c0,c1)))
print([(len(x[0]),x[2],len(x[1])) for x in sel])

